      "ruby": "<ruby>見<rt>み</rt></ruby>よ、<ruby>処女<rt>しょじょ</rt></ruby>がみごもっている。そして<ruby>男<rt>おとこ</rt></ruby>の<ruby>子<rt>こ</rt></ruby>を<ruby>産<rt>う</rt></ruby>む。その<ruby>名<rt>な</rt></ruby>はインマヌエルと<ruby>呼<rt>よ</rt></ruby>ばれる。",
      "romaji": "miyo,shojogamigomotteiru.soshiteotokonokowoumu.sononahainnmanuerutoyobareru."
