    {
      "id": "cook-035",
      "text": "『あなたの重荷を主にゆだねよ。』\n(詩篇 55:22)\nひと休みして、肩の力を抜いてリフレッシュしよう🌿",
      "category": "scripture"
    },
    {
      "id": "cook-036",
      "text": "『光は闇の中に輝いている。』\n(ヨハネ 1:5)\n君の毎日の頑張りは、きっと光り輝くよ！✨",
      "category": "scripture"
    },
    {
      "id": "cook-037",
      "text": "『希望を抱いて喜び、患難に耐え、絶えず祈りに励みなさい。』\n(ローマ 12:12)\nタイピングも毎日少しずつの積み重ねだね！👍",
      "category": "scripture"
    },
    {
      "id": "cook-038",
      "text": "休日の朝はカフェでゆったり過ごすみたいに、リラックスしてね☕",
      "category": "idle"
    },
    {
      "id": "cook-039",
      "text": "今日も頑張ってるね！えらい！",
      "category": "idle"
    },
    {
      "id": "cook-040",
      "text": "長いドライブの途中のように、時々は休憩も大事だよ🚗",
      "category": "idle"
    },
    {
      "id": "cook-041",
      "text": "温泉に浸かっている気分で、肩の力を抜いてみよう♨️",
      "category": "idle"
    },
    {
      "id": "cook-042",
      "text": "君のタイピング、とってもかっこいい！",
      "category": "idle"
    },
    {
      "id": "cook-043",
      "text": "綺麗な日本庭園を歩くみたいに、心を落ち着かせてね🌿",
      "category": "idle"
    },
    {
      "id": "cook-044",
      "text": "流れるようなタイピング！景色が飛んでいくみたいだね🚗💨",
      "category": "combo"
    },
    {
      "id": "cook-045",
      "text": "最高！その集中力、素晴らしいよ！✨",
      "category": "combo"
    },
    {
      "id": "cook-046",
      "text": "ちょっと画面から目を離して、遠くの緑を見てみるのもいいかも🌿",
      "category": "rest"
    },
    {
      "id": "cook-047",
      "text": "温かいコーヒーを飲んで、一息つこう☕",
      "category": "rest"
    },
    {
      "id": "cook-048",
      "text": "肩の力を抜いて、リラックス、リラックス♨️",
      "category": "rest"
    },
    {
      "id": "cook-049",
      "text": "今日はどんなご飯を食べたの？\nクックはニンジンケーキが好きだよ🥕",
      "category": "idle"
    },
    {
      "id": "cook-050",
      "text": "たまには甘いものを食べて、脳に栄養をあげようね！🍰",
      "category": "idle"
    },
    {
      "id": "cook-051",
      "text": "外の空気でも吸ってみる？\n気分転換はすごく大事だよ！🍃",
      "category": "idle"
    },
    {
      "id": "cook-052",
      "text": "コーヒーの香りでホッと一息...\n一緒に休憩しよう☕",
      "category": "idle"
    },
    {
      "id": "cook-053",
      "text": "ふわぁ...なんだか眠くなってきちゃった...💤\n君も無理しないでね。",
      "category": "idle"
    },
    {
      "id": "cook-054",
      "text": "長いドライブの途中のように、時々はサービスエリアで休むのも大事だよ🚗",
      "category": "idle"
    },
    {
      "id": "cook-055",
      "text": "キーボードの「F」と「J」にあるポッチを触ってみて。\nそこがホームポジションだよ！👆",
      "category": "idle"
    },
    {
      "id": "cook-056",
      "text": "手元を見ないで画面の文字をしっかり見るのが、速くなるコツだよ！👀",
      "category": "idle"
    },
    {
      "id": "cook-057",
      "text": "焦らず正確に打つのが、一番の上達への近道なんだ🐰",
      "category": "idle"
    },
    {
      "id": "cook-058",
      "text": "クックの耳はよく聞こえるんだよ！君のタイピングの音もね♪👂",
      "category": "idle"
    },
    {
      "id": "cook-059",
      "text": "土星の輪っかって、実は氷の粒でできているんだよ🪐\n冷たくて気持ちいい〜",
      "category": "idle"
    },
    {
      "id": "cook-060",
      "text": "宇宙からずっと君のことを見守っているよ！🔭",
      "category": "idle"
    },
    {
      "id": "cook-061",
      "text": "さあ、次のクエストに行ってみよう！🗡️",
      "category": "idle"
    },
    {
      "id": "cook-062",
      "text": "いらっしゃい！サウンドがONになったよ♪",
      "category": "event"
    },
    {
      "id": "cook-063",
      "text": "『心を尽くして主に拠り頼め。』\n(箴言 3:5)\n祈る時間も大切だね。自分のペースで進もう☕",
      "category": "scripture"
    },
    {
      "id": "cook-064",
      "text": "『恐れるな。わたしはあなたとともにいる。』\n(イザヤ 41:10)\nいつでもクックが祈りながら応援してるからね！🪐",
      "category": "scripture"
    },
    {
      "id": "cook-065",
      "text": "惜しかったね…祈りながら再挑戦だ！",
      "category": "event"
    },
    {
      "id": "cook-066",
      "text": "テーマ練習だね！自分のペースで頑張ろう！",
      "category": "event"
    },
    {
      "id": "cook-067",
      "text": "よく頑張ったね！御言葉が心に刻まれたよ✨",
      "category": "event"
    },
    {
      "id": "cook-068",
      "text": "この難易度の問題がないから、テーマ内の全部の中から出すね！",
      "category": "event"
    },
    {
      "id": "cook-069",
      "text": "テーマ練習スタート！自分のペースで頑張ろう！",
      "category": "event"
    },
    {
      "id": "cook-070",
      "text": "『いつも喜んでいなさい。』\n(第一テサロニケ 5:16)",
      "category": "scripture"
    },
    {
      "id": "cook-071",
      "text": "『神は愛です。』\n(第一ヨハネ 4:16)",
      "category": "scripture"
    },
    {
      "id": "cook-072",
      "text": "『強くあれ。雄々しくあれ。』\n(ヨシュア記 1:9)",
      "category": "scripture"
    },
    {
      "id": "cook-073",
      "text": "この難易度の問題がないから全部の中から出すね！",
      "category": "event"
    },
    {
      "id": "cook-074",
      "text": "サウンドONで冒険に出発するよ♪",
      "category": "event"
    },
    {
      "id": "cook-075",
      "text": "サウンドOFFで静かに進めるね☕",
      "category": "event"
    }
