      "jp": "神よ、あなたは私たちをあなたに向けてお造りになりました。私たちの心は、あなたの内に憩うまで安らうことがありません。",
      "kana": "かみよ、あなたはわたしたちをあなたにむけておつくりになりました。わたしたちのこころは、あなたのうちにいこうまでやすらうことがありません。",
      "ruby": "<ruby>神<rt>かみ</rt></ruby>よ、あなたは<ruby>私<rt>わたし</rt></ruby>たちをあなたに<ruby>向<rt>む</rt></ruby>けてお<ruby>造<rt>つく</rt></ruby>りになりました。<ruby>私<rt>わたし</rt></ruby>たちの<ruby>心<rt>こころ</rt></ruby>は、あなたの<ruby>内<rt>うち</rt></ruby>に<ruby>憩<rt>いこ</rt></ruby>うまで<ruby>安<rt>やす</rt></ruby>らうことがありません。",
